COMMENT ON TABLE landing IS '进港卸渔报告';
COMMENT ON COLUMN landing.trip_code IS '航次业务编号';
COMMENT ON COLUMN landing.landed_at IS '进港时刻（UTC）';
COMMENT ON COLUMN landing.total_kg IS '卸渔总量（千克）';
