183	    public LogbookResponse submitLogbook(LogbookRequest request) {
184	        String fingerprint = fingerprint(Map.of(
185	                "op", OP_LOGBOOK,
186	                "tripCode", request.tripCode(),
187	                "zoneCode", request.zoneCode(),
188	                "fishingAt", request.fishingAt().toString(),
189	                "lines", normalizedLines(request.lines().stream()
190	                        .map(l -> Map.of("speciesCode", l.speciesCode(), "weightKg", l.weightKg().toPlainString()))
191	                        .toList())));
192	        AcquireResult acquired = idempotencyRepo.acquire(
193	                request.requestId(), OP_LOGBOOK, fingerprint, Instant.now(clock));
194	        switch (acquired.outcome()) {
195	            case REPLAY -> {
196	                return replay(acquired.responseJson(), LogbookResponse.class);
197	            }
198	            case MISMATCH -> throw new ConflictException("相同 requestId 已用于不同业务参数");
199	            case IN_PROGRESS -> throw new ConflictException("相同 requestId 请求正在处理中");
200	            default -> { }
201	        }
202	
203	        TripRow trip = requireTrip(request.tripCode());
204	        request.lines().forEach(l -> requireSpecies(l.speciesCode()));
205	
206	        LocalDate logDate = request.fishingAt().atZone(ZoneOffset.UTC).toLocalDate();
207	        // 按“船＋日期＋渔区”去重
208	        LogbookRow duplicate = logbookRepo
209	                .findByVesselDateZone(trip.vesselCode(), logDate, request.zoneCode()).orElse(null);
210	        if (duplicate != null) {
211	            throw new ConflictException("渔船 " + trip.vesselCode() + " 在 " + logDate + " 渔区 "
212	                    + request.zoneCode() + " 已存在渔捞日志，按船＋日期＋渔区去重");
213	        }
214	
215	        Map<String, BigDecimal> catchLines = mergePositiveLines(request.lines().stream()
216	                .map(l -> new WeightLineView(l.speciesCode(), l.weightKg())).toList());
217	        BigDecimal total = catchLines.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
218	        BigDecimal bycatchKg = catchLines.entrySet().stream()
219	                .filter(e -> {
220	                    SpeciesRow species = catalogRepo.findSpecies(e.getKey());
221	                    return species != null && species.protectedSpecies();
222	                })
223	                .map(Map.Entry::getValue)
224	                .reduce(BigDecimal.ZERO, BigDecimal::add);
225	        // 兼捕比例（百分比，4 位小数）；恰 5% 合法，严格大于才标注审查。
226	        BigDecimal bycatchPct = bycatchKg.multiply(BigDecimal.valueOf(100))
227	                .divide(total, 4, RoundingMode.HALF_UP);
228	        boolean bycatchFlagged = bycatchPct.compareTo(BYCATCH_LIMIT_PCT) > 0;
229	
230	        Instant now = Instant.now(clock);
231	        boolean late = trip.status() == TripStatus.CLOSED;
232	
233	        int seqNo = (int) logbookRepo.findByTrip(request.tripCode()).stream()
234	                .filter(r -> !r.late())
235	                .count() + 1;
236	        long logId = logbookRepo.insert(new LogbookRow(null, request.tripCode(), trip.vesselCode(),
237	                request.zoneCode(), logDate, request.fishingAt(), total, bycatchFlagged, late, seqNo, now));
238	        catchLines.forEach((speciesCode, weight) -> logbookRepo.insertLine(logId, speciesCode, weight));
239	        logbookRepo.renumberSequence(request.tripCode());
240	
241	        boolean reviewOpened = false;
242	        if (late) {
243	            // 结案后迟到日志：只记迟到事件并入审查队列，不参与核销。
244	            logbookRepo.insertLateEvent(request.tripCode(), trip.vesselCode(), request.zoneCode(),
245	                    logDate, request.fishingAt(), toJson(request), now);
246	            reviewRepo.insert(request.tripCode(), trip.vesselCode(), ReviewReason.LATE_LOG,
247	                    "结案后迟到日志：渔区 " + request.zoneCode() + "，作业时刻 " + request.fishingAt(), now);
248	            reviewOpened = true;
249	        } else if (bycatchFlagged) {
250	            // 兼捕保护鱼种超比例：该航次日志单独标注并触发审查，冻结该船配额余额。
251	            reviewRepo.insert(request.tripCode(), trip.vesselCode(), ReviewReason.BYCATCH_RATIO,
252	                    "兼捕保护鱼种占比 " + bycatchPct.toPlainString() + "% 超过允许 5%", now);
253	            if (!trip.frozen()) {
254	                tripRepo.updateState(request.tripCode(), TripStatus.IN_REVIEW, true, now);
255	            }
256	            reviewOpened = true;
257	        }
258	
259	        if (!late) {
260	            recomputeLoggedCatch(request.tripCode());
261	        }
262	
263	        LogbookRow saved = logbookRepo.findById(logId).orElseThrow();
264	        LogbookResponse response = new LogbookResponse(saved.id(), request.tripCode(), request.zoneCode(),
265	                logDate, request.fishingAt(), saved.seqNo(), total, bycatchFlagged, late, reviewOpened,
266	                toViews(catchLines), false);
267	        idempotencyRepo.saveResponse(request.requestId(), toJson(response));
268	        return response;
269	    }
