275	    @Transactional
276	    public LandingResponse reportLanding(LandingRequest request) {
277	        String fingerprint = fingerprint(Map.of(
278	                "op", OP_LANDING,
279	                "tripCode", request.tripCode(),
280	                "landedAt", request.landedAt().toString(),
281	                "explanation", request.deviationExplanation() == null ? "" : request.deviationExplanation(),
282	                "lines", normalizedLines(request.lines().stream()
283	                        .map(l -> Map.of("speciesCode", l.speciesCode(), "weightKg", l.weightKg().toPlainString()))
284	                        .toList())));
285	        AcquireResult acquired = idempotencyRepo.acquire(
286	                request.requestId(), OP_LANDING, fingerprint, Instant.now(clock));
287	        switch (acquired.outcome()) {
288	            case REPLAY -> {
289	                return replay(acquired.responseJson(), LandingResponse.class);
290	            }
291	            case MISMATCH -> throw new ConflictException("相同 requestId 已用于不同业务参数");
292	            case IN_PROGRESS -> throw new ConflictException("相同 requestId 请求正在处理中");
293	            default -> { }
294	        }
295	
296	        TripRow trip = requireTripForUpdate(request.tripCode());
297	        if (trip.status() == TripStatus.CLOSED) {
298	            throw new BusinessRuleException("航次 " + request.tripCode() + " 已结案，不能再提交进港报告");
299	        }
300	        if (landingRepo.findByTrip(request.tripCode()).isPresent()) {
301	            throw new ConflictException("航次 " + request.tripCode() + " 已提交进港报告");
302	        }
303	        request.lines().forEach(l -> requireSpecies(l.speciesCode()));
304	
305	        Map<String, BigDecimal> landed = mergePositiveLines(request.lines().stream()
306	                .map(l -> new WeightLineView(l.speciesCode(), l.weightKg())).toList());
307	        Map<String, BigDecimal> logged = effectiveLoggedMap(request.tripCode());
308	        if (logged.isEmpty()) {
309	            throw new BusinessRuleException("航次 " + request.tripCode() + " 尚无有效渔捞日志，不能进港报告");
310	        }
311	
312	        BigDecimal maxDeviation = BigDecimal.ZERO;
313	        String deviationSpecies = null;
314	        for (Map.Entry<String, BigDecimal> entry : logged.entrySet()) {
315	            BigDecimal landedWeight = landed.getOrDefault(entry.getKey(), BigDecimal.ZERO);
316	            BigDecimal diff = landedWeight.subtract(entry.getValue()).abs();
317	            BigDecimal pct = diff.multiply(BigDecimal.valueOf(100))
318	                    .divide(entry.getValue(), 4, RoundingMode.HALF_UP);
319	            if (pct.compareTo(maxDeviation) > 0) {
320	                maxDeviation = pct;
321	                deviationSpecies = entry.getKey();
322	            }
323	        }
324	        // 恰 3% 视为一致；严格大于须提交差异说明并转人工复核。
325	        boolean deviationOver = maxDeviation.compareTo(DEVIATION_LIMIT_PCT) > 0;
326	        if (deviationOver) {
327	            if (request.deviationExplanation() == null || request.deviationExplanation().isBlank()) {
328	                throw new BusinessRuleException("鱼种 " + deviationSpecies + " 卸渔偏差 "
329	                        + maxDeviation.toPlainString() + "% 超过 3%，须提交差异说明");
330	            }
331	        }
332	
333	        Instant now = Instant.now(clock);
334	        BigDecimal totalLanded = landed.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
335	        long landingId = landingRepo.insert(new LandingRow(null, request.tripCode(), request.landedAt(),
336	                totalLanded, maxDeviation, deviationOver,
337	                deviationOver ? request.deviationExplanation() : null, now));
338	        landed.forEach((speciesCode, weight) -> landingRepo.insertLine(landingId, speciesCode, weight));
339	        tripRepo.markLanded(request.tripCode(), request.landedAt(), now);
340	
341	        // 口径行：无复核时以日志累计量为核销最终口径；有偏差复核时待复核结论覆盖。
342	        landed.forEach((speciesCode, weight) ->
343	                tripRepo.updateLandedKg(request.tripCode(), speciesCode, weight,
344	                        deviationOver ? BigDecimal.ZERO : logged.getOrDefault(speciesCode, BigDecimal.ZERO)));
345	        logged.forEach((speciesCode, weight) -> {
346	            if (!landed.containsKey(speciesCode)) {
347	                tripRepo.updateLandedKg(request.tripCode(), speciesCode, BigDecimal.ZERO,
348	                        deviationOver ? BigDecimal.ZERO : weight);
349	            }
350	        });
351	
352	        if (deviationOver) {
353	            reviewRepo.insert(request.tripCode(), trip.vesselCode(), ReviewReason.LANDING_DEVIATION,
354	                    "卸渔偏差 " + maxDeviation.toPlainString() + "%（鱼种 " + deviationSpecies
355	                            + "）；差异说明：" + request.deviationExplanation(), now);
356	        }
357	
358	        long openReviews = reviewRepo.countOpenForTrip(request.tripCode());
359	        boolean frozen = openReviews > 0;
360	        TripStatus newStatus = frozen ? TripStatus.IN_REVIEW : TripStatus.DISCHARGED;
361	        tripRepo.updateState(request.tripCode(), newStatus, frozen, now);
362	
363	        LandingResponse response = new LandingResponse(request.tripCode(), newStatus, request.landedAt(),
364	                maxDeviation, deviationOver, toViews(landed), toViews(logged), false);
365	        idempotencyRepo.saveResponse(request.requestId(), toJson(response));
366	        return response;
367	    }
