package com.example.starter.fishery.domain;

/**
 * 跨船配额调剂单状态：PENDING 待对方确认，EFFECTIVE 双方确认已生效，EXPIRED 48 小时未确认已失效。
 */
public enum TransferStatus {
    /** 待对方确认（发起方提交即视为发起方已确认）。 */
    PENDING,
    /** 双方确认，调剂量已在同一事务内完成双方额度变更。 */
    EFFECTIVE,
    /** 确认时限（UTC 48 小时，恰满即失效）内未确认，额度不变，可重新发起。 */
    EXPIRED
}

package com.example.starter.fishery.db;

import com.example.starter.fishery.domain.TransferStatus;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 跨船配额调剂单行：{@code amountKg} 为调剂量（千克），{@code expiresAt} 为确认截止时刻
 * （UTC，发起后 48 小时，恰满未确认自动失效），{@code confirmedAt} 未确认为空。
 */
public record TransferRow(
        Long id,
        String requestId,
        String fromVesselCode,
        String toVesselCode,
        String speciesCode,
        int quotaYear,
        BigDecimal amountKg,
        TransferStatus status,
        Instant createdAt,
        Instant expiresAt,
        Instant confirmedAt) {
}

package com.example.starter.fishery.db;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 年度结转台账行：{@code quotaYear} 为结转目标年度（次年），{@code carriedKg} 为结转额度（千克），
 * {@code usedKg} 为次年已优先核销的结转额度（千克）。
 */
public record CarryoverRow(
        Long id,
        String vesselCode,
        String speciesCode,
        int quotaYear,
        int sourceYear,
        BigDecimal carriedKg,
        BigDecimal usedKg,
        Instant createdAt) {

    /** 次年剩余可优先核销的结转额度（千克）。 */
    public BigDecimal remainingKg() {
        return carriedKg.subtract(usedKg);
    }
}

